// File: Nexotv/iptv/player/home/HomeGuideArtworkRepository.ktpackage Nexotv.iptv.player.homeimport Nexotv.iptv.player.tv.*import Nexotv.iptv.player.*import Nexotv.iptv.player.recordings.*import android.content.Contextimport android.graphics.Bitmapimport android.graphics.BitmapFactoryimport android.net.Uriimport android.util.Logimport androidx.annotation.DrawableResimport androidx.core.net.toUriimport androidx.tvprovider.media.tv.ChannelLogoUtilsimport Nexotv.iptv.player.guide.GuideProgramTimeIndeximport Nexotv.iptv.player.guide.TvProgramJsonimport Nexotv.iptv.player.guide.XmlTvGuide/** Caches the guide snapshot and provides artwork URIs and the Android TV channel logo. */internal class HomeGuideArtworkRepository {    private val tag = "${BuildConfig.BRAND_NAME}HomeArtwork"    private val preferencesName = "${BuildConfig.BRAND_KEY}_player"    private val guideCacheKey = "epg_cache"    private val guideLock = Any()    private var cachedGuideRaw: String? = null    private var cachedGuide: HomeGuideSnapshot? = null    private var failedGuideRaw: String? = null    private val logoLock = Any()    private var cachedLogo: Bitmap? = null    private var logoStoredForChannelId: Long? = null    private val emptyGuide: HomeGuideSnapshot by lazy {        HomeGuideSnapshot(emptyList(), GuideProgramTimeIndex(emptyList()))    }    fun guideSnapshot(context: Context): HomeGuideSnapshot {        val raw = readGuideRaw(context) ?: return lastKnownGuide()        return synchronized(guideLock) {            val cached = cachedGuide            when {                cached != null && raw == cachedGuideRaw -> cached                raw == failedGuideRaw -> cached ?: emptyGuide                else -> rebuildGuide(raw, cached)            }        }    }    fun liveArtUri(context: Context): Uri {        val icon: String? = try {            val now = System.currentTimeMillis()            val guide = guideSnapshot(context)            val current = if (guide.programs.isEmpty()) null else guide.timeIndex.at(now)            current?.iconUrl        } catch (t: Throwable) {            if (!t.isRecoverable()) throw t            Log.w(tag, "No se pudo resolver la ilustración del programa actual", t)            null        }        return recordingArtUri(context, icon, R.drawable.guide_placeholder)    }    fun ensureChannelLogo(context: Context, channelId: Long) {        if (channelId <= 0L) {            Log.w(tag, "Identificador de canal no válido: $channelId")            return        }        synchronized(logoLock) {            if (logoStoredForChannelId == channelId) return            try {                val stored = ChannelLogoUtils.storeChannelLogo(                    appContext(context),                    channelId,                    channelLogo(context),                )                if (stored) {                    logoStoredForChannelId = channelId                } else {                    Log.w(tag, "El sistema rechazó el logo del canal")                }            } catch (t: Throwable) {                if (!t.isRecoverable()) throw t                Log.w(tag, "No se pudo actualizar el logo del canal", t)            }        }    }    fun invalidateChannelLogo() {        synchronized(logoLock) { logoStoredForChannelId = null }    }    fun recordingArtUri(        context: Context,        icon: String?,        @DrawableRes fallbackResource: Int = R.drawable.recording_placeholder,    ): Uri = parseRemoteArtUri(icon) ?: fallbackArtUri(context, fallbackResource)    private fun appContext(context: Context): Context = context.applicationContext ?: context    private fun Throwable.isRecoverable(): Boolean = this is Exception || this is OutOfMemoryError    private fun readGuideRaw(context: Context): String? = try {        appContext(context)            .getSharedPreferences(preferencesName, Context.MODE_PRIVATE)            .getString(guideCacheKey, EMPTY_GUIDE_JSON)            .orEmpty()    } catch (t: Throwable) {        if (!t.isRecoverable()) throw t        Log.w(tag, "No se pudo leer la guía en caché", t)        null    }    private fun lastKnownGuide(): HomeGuideSnapshot = synchronized(guideLock) { cachedGuide ?: emptyGuide }    /** Must be invoked while holding [guideLock]. */    private fun rebuildGuide(raw: String, previous: HomeGuideSnapshot?): HomeGuideSnapshot = try {        val decoded = decodeGuide(raw)        cachedGuide = decoded        cachedGuideRaw = raw        failedGuideRaw = null        decoded    } catch (t: Throwable) {        if (!t.isRecoverable()) throw t        failedGuideRaw = raw        Log.w(tag, "No se pudo decodificar la guía en caché", t)        previous ?: emptyGuide    }    private fun decodeGuide(raw: String): HomeGuideSnapshot {        if (raw.isBlank()) return emptyGuide        val programs = XmlTvGuide.discardSharedArtwork(TvProgramJson.decode(raw))            .sortedBy(TvProgram::startMs)        return HomeGuideSnapshot(programs, GuideProgramTimeIndex(programs))    }    private fun parseRemoteArtUri(icon: String?): Uri? {        val candidate = icon?.trim().orEmpty()        if (candidate.isEmpty() || candidate.length > MAX_ART_URI_LENGTH) return null        val isHttp = candidate.startsWith("https://", ignoreCase = true) ||            candidate.startsWith("http://", ignoreCase = true)        if (!isHttp || candidate.any { it.isISOControl() }) return null        return try {            val uri = candidate.replace(" ", "%20").toUri().normalizeScheme()            if (uri.host.isNullOrBlank()) null else uri        } catch (e: Exception) {            null        }    }    private fun fallbackArtUri(context: Context, @DrawableRes resource: Int): Uri {        val safeResource = if (resource > 0) resource else R.drawable.recording_placeholder        return "android.resource://${appContext(context).packageName}/$safeResource".toUri()    }    private fun channelLogo(context: Context): Bitmap = synchronized(logoLock) {        cachedLogo?.takeIf { !it.isRecycled }?.let { return it }        val source = BitmapFactory.decodeResource(appContext(context).resources, R.drawable.channel_artwork)            ?: error("No se pudo cargar el logo de ${BuildConfig.BRAND_NAME}")        val icon = try {            cropLogo(source)        } catch (t: Throwable) {            source.recycle()            throw t        }        if (icon !== source) source.recycle()        cachedLogo = icon        icon    }    private fun cropLogo(source: Bitmap): Bitmap {        val sourceWidth = source.width        val sourceHeight = source.height        if (sourceWidth <= 0 || sourceHeight <= 0) return source        val left = (sourceWidth * LOGO_LEFT_FRACTION).toInt().coerceIn(0, sourceWidth - 1)        val top = (sourceHeight * LOGO_TOP_FRACTION).toInt().coerceIn(0, sourceHeight - 1)        val width = (sourceWidth * LOGO_WIDTH_FRACTION).toInt().coerceIn(1, sourceWidth - left)        val height = (sourceHeight * LOGO_HEIGHT_FRACTION).toInt().coerceIn(1, sourceHeight - top)        return Bitmap.createBitmap(source, left, top, width, height)    }    private companion object {        const val EMPTY_GUIDE_JSON: String = "[]"        const val MAX_ART_URI_LENGTH: Int = 4096        const val LOGO_LEFT_FRACTION: Float = 0.27f        const val LOGO_TOP_FRACTION: Float = 0.01f        const val LOGO_WIDTH_FRACTION: Float = 0.53f        const val LOGO_HEIGHT_FRACTION: Float = 0.65f    }}